/* v7 · 云控：存量包的更新入口防护 + 在线修正微信一键直达链（cfg.quickActions）。
   与 v6 的关键差异：带 apkUpdateMulti 桥的新包（v5.23-fix1）完全不被热更干预，
   由源码走应用内多源下载；只有老包才沿用 v6 的浏览器下载页改道。 */
(function (w, d) {
  var N = w.ZhikeNative;
  var legacy = !N || typeof N.apkUpdateMulti !== "function";
  if (!legacy) return;
  var URL = "https://1855215134.share.123pan.cn/123pan/lmaCvd-nid8h?pwd=f3sa#";
  var PW  = "f3sa";
  var last = 0;
  function open() {
    var now = Date.now();
    if (now - last < 800) return;
    last = now;
    if (N && typeof N.openDownloadPage === "function") {
      try { N.openDownloadPage(URL, PW); return; } catch (e) {}
    }
    if (N && typeof N.openUrl === "function") {
      try { N.openUrl(URL); return; } catch (e) {}
    }
    try { w.open(URL, "_blank", "noopener,noreferrer"); } catch (e) {}
  }
  w.canInAppDownload = function(){ return false; };
  w.checkUpdate = open; w.startApkUpdate = open;
  w.openDownloadLegacy = open; w.showUpdSheet = open;
  if (!w.__zkUpdHotV7) {
    w.__zkUpdHotV7 = 1;
    w.addEventListener("click", function (e) {
      var t = e.target;
      if (!t || !t.closest) return;
      if (t.closest("#zk-upgrade, #btn-check-update, [data-zk='check-update']")) {
        e.preventDefault(); e.stopImmediatePropagation(); open();
      }
    }, true);
  }
})(window, document);
